import { useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

export type UserStatus = 'active' | 'disabled';

export interface User {
  id: string;
  name: string;
  role: string;
  status: UserStatus;
}

export interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

const STATUS_LABEL: Record<UserStatus, string> = {
  active: 'Активен',
  disabled: 'Отключён',
};

const STATUS_CLASS: Record<UserStatus, string> = {
  active: 'jx-badge jx-badge--success',
  disabled: 'jx-badge jx-badge--muted',
};

export default function UsersTable({ users }: UsersTableProps) {
  const [requestedPage, setRequestedPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const page = Math.min(requestedPage, pageCount);
  const pages = useMemo(
    () => Array.from({ length: pageCount }, (_, index) => index + 1),
    [pageCount],
  );
  const rows = useMemo(
    () => users.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE),
    [users, page],
  );

  return (
    <div
      className="jx-stack"
      style={{ display: 'grid', gap: 'var(--jx-space-4)' }}
    >
      <table className="jx-table">
        <caption className="jx-visually-hidden">Пользователи</caption>
        <thead className="jx-table__head">
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody className="jx-table__body">
          {rows.length === 0 ? (
            <tr>
              <td colSpan={3} className="jx-table__empty">
                Пользователей нет
              </td>
            </tr>
          ) : (
            rows.map((user) => (
              <tr key={user.id} className="jx-table__row">
                <td>{user.name}</td>
                <td>{user.role}</td>
                <td>
                  <span className={STATUS_CLASS[user.status]}>
                    {STATUS_LABEL[user.status]}
                  </span>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>

      <nav
        className="jx-pagination"
        aria-label="Навигация по страницам"
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 'var(--jx-space-2)',
        }}
      >
        <Button
          type="button"
          disabled={page === 1}
          onClick={() => setRequestedPage(page - 1)}
        >
          Назад
        </Button>
        {pages.map((pageNumber) => (
          <Button
            key={pageNumber}
            type="button"
            aria-current={pageNumber === page ? 'page' : undefined}
            onClick={() => setRequestedPage(pageNumber)}
          >
            {pageNumber}
          </Button>
        ))}
        <Button
          type="button"
          disabled={page === pageCount}
          onClick={() => setRequestedPage(page + 1)}
        >
          Вперёд
        </Button>
      </nav>
    </div>
  );
}

